window.__votdWeek && window.__votdWeek({"week":"2028-04-17","reading":"Mosiah 1–3","days":[{"d":"2028-04-17","ref":"Mosiah 1:1","b":"Mosiah","c":1,"v":1,"he":"וְעַתָּה לֹא־הָיְתָה עוֹד מְרִיבָה בְּכׇל־אֶרֶץ זָרַהֶמְלָה בְּקֶרֶב כׇּל־הָעָם אֲשֶׁר הָיוּ לַמֶּלֶךְ בִּנְיָמִין וַיְהִי לַמֶּלֶךְ בִּנְיָמִין שָׁלוֹם תָּמִיד כׇּל־יֶתֶר יָמָיו׃","en":"And now there was no more contention in all the land of Zarahemla, among all the people who belonged to king Benjamin, so that king Benjamin had continual peace all the remainder of his days."},{"d":"2028-04-18","ref":"Mosiah 2:3","b":"Mosiah","c":2,"v":3,"he":"וַיִּקְחוּ גַם מִבְּכוֹרוֹת צֹאנָם לִזְבֹּחַ זְבָחִים וּלְהַעֲלוֹת עֹלוֹת כְּתוֹרַת מֹשֶׁה׃","en":"And they also took of the firstlings of their flocks, that they might offer sacrifice and burnt offerings according to the law of Moses;"},{"d":"2028-04-19","ref":"Mosiah 2:17","b":"Mosiah","c":2,"v":17,"he":"וְהִנֵּה אֲנִי מַגִּיד לָכֶם אֶת־הַדְּבָרִים הָאֵלֶּה לְמַעַן תִּלְמְדוּ חׇכְמָה לְמַעַן תֵּדְעוּ כִּי בַּעֲבֹדַתְכֶם אֶת־אֲחֵיכֶם רַק בַּעֲבֹדַת אֱלֹהֵיכֶם אַתֶּם׃","en":"And behold, I tell you these things that ye may learn wisdom; that ye may learn that when ye are in the service of your fellow beings ye are only in the service of your God."},{"d":"2028-04-20","ref":"Mosiah 2:41","b":"Mosiah","c":2,"v":41,"he":"וְעוֹד הִנְנִי מְבַקֵּשׁ כִּי תַּחְשְׁבוּ עַל־אֹשֶׁר וְשִׂמְחַת שֹׁמְרֵי מִצְוֹת־אֱלֹהִים כִּי הִנֵּה מְבֹרָכִים הֵם בְּכׇל־דָּבָר גַּם־בְּגוּף וְגַם־בְּרוּחַ וְאִם־יַחֲזִיקוּ בֶּאֱמוּנָה עַד־הַקֵּץ יִתְקַבְּלוּ בַּשָּׁמַיִם לְמַעַן יִשְׁכְּנוּ עִם־אֱלֹהִים בְּשִׂמְחַת עוֹלָם זִכְרוּ זִכְרוּ כִּי הַדְּבָרִים הָאֵלֶּה אֱמֶת כִּי דִּבֵּר יְהוָה אֱלֹהִים׃","en":"And moreover, I would desire that ye should consider on the blessed and happy state of those that keep the commandments of God. For behold, they are blessed in all things, both temporal and spiritual; and if they hold out faithful to the end they are received into heaven, that thereby they may dwell with God in a state of never-ending happiness. O remember, remember that these things are true; for the Lord God hath spoken it."},{"d":"2028-04-21","ref":"Mosiah 3:8","b":"Mosiah","c":3,"v":8,"he":"וְיִקָּרֵא שְׁמוֹ יֵשׁוּעַ הַמָּשִׁיחַ בֶּן־אֱלֹהִים אֲבִי הַשָּׁמַיִם וְהָאָרֶץ בּוֹרֵא כׇל־דָּבָר מֵרֵאשִׁית וְשֵׁם אִמּוֹ מִרְיָם׃","en":"And he shall be called Jesus Christ, the Son of God, the Father of heaven and earth, the Creator of all things from the beginning; and his mother shall be called Mary."},{"d":"2028-04-22","ref":"Mosiah 3:14","b":"Mosiah","c":3,"v":14,"he":"וַיַּרְא יְהוָה אֱלֹהִים כִּי עַם־קְשֵׁה־עֹרֶף הֵם וַיִּתֵּן־לָהֶם תּוֹרָה הִיא תּוֹרַת מֹשֶׁה׃","en":"Yet the Lord God saw that his people were a stiffnecked people, and he appointed unto them a law, even the law of Moses."},{"d":"2028-04-23","ref":"Mosiah 3:19","b":"Mosiah","c":3,"v":19,"he":"כִּי הָאָדָם אֲשֶׁר בַּבָּשָׂר אוֹיֵב לֵאלֹהִים הוּא וְהָיָה מִנְּפִילַת אָדָם וְיִהְיֶה לְעוֹלָם וָעֶד אִם־לֹא יִכָּנַע לְפַתּוֹת רוּחַ־הַקֹּדֶשׁ וְיָסִיר אֶת־הָאָדָם אֲשֶׁר בַּבָּשָׂר וְיִהְיֶה לְקָדוֹשׁ דֶּרֶךְ כַּפָּרַת הַמָּשִׁיחַ הָאָדוֹן וְיִהְיֶה כְּיֶלֶד נִכְנָע עָנָו שָׁפָל רוּחַ אֶרֶךְ־אַפַּיִם מָלֵא אַהֲבָה נָכוֹן לְהִכָּנַע לְכׇל־אֲשֶׁר יִרְאֶה הָאָדוֹן לְהַטִּיל עָלָיו כַּאֲשֶׁר יִכָּנַע הַיֶּלֶד לְאָבִיו׃","en":"For the natural man is an enemy to God, and has been from the fall of Adam, and will be, forever and ever, unless he yields to the enticings of the Holy Spirit, and putteth off the natural man and becometh a saint through the atonement of Christ the Lord, and becometh as a child, submissive, meek, humble, patient, full of love, willing to submit to all things which the Lord seeth fit to inflict upon him, even as a child doth submit to his father."}]});
